--
-- Name: begin_legacy_csv_restore(); Type: FUNCTION; Schema: analytics; Owner: migration_owner
--

CREATE FUNCTION analytics.begin_legacy_csv_restore() RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'analytics'
    AS $$
DECLARE anchor timestamptz;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('analytics.rebuild_core_projections',0));
    LOCK TABLE analytics.dataset_revision IN SHARE MODE;
    SELECT committed_at INTO anchor FROM analytics.dataset_revision
        WHERE id=(SELECT max(dataset_revision_id) FROM analytics.projection_state WHERE status='ready');
    IF anchor IS NULL THEN RAISE EXCEPTION 'published revision required for archive restore'; END IF;
    RETURN anchor;
END $$;


ALTER FUNCTION analytics.begin_legacy_csv_restore() OWNER TO migration_owner;

--
-- Name: capture_legacy_csv_facts(date); Type: FUNCTION; Schema: analytics; Owner: migration_owner
--

CREATE FUNCTION analytics.capture_legacy_csv_facts(p_month date DEFAULT NULL::date) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'analytics', 'ingest'
    AS $$
DECLARE written bigint;
BEGIN
    INSERT INTO analytics.legacy_csv_snapshot_fact
    SELECT published_month,id,publication_id,observed_at,age_seconds,sampling_bucket,
        views_count,reactions_count,comments_count,shares_count,correction_sequence
    FROM ingest.publication_metric_snapshot WHERE p_month IS NULL OR published_month=p_month
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS written=ROW_COUNT;RETURN written;
END $$;


ALTER FUNCTION analytics.capture_legacy_csv_facts(p_month date) OWNER TO migration_owner;

--
-- Name: guard_legacy_period_policy(); Type: FUNCTION; Schema: analytics; Owner: migration_owner
--

CREATE FUNCTION analytics.guard_legacy_period_policy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'analytics'
    AS $$
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('analytics.rebuild_core_projections',0));
    IF NEW.effective_from_revision<=coalesce((SELECT max(dataset_revision_id) FROM analytics.projection_state),0)
       OR NEW.effective_from_revision<=coalesce((SELECT max(effective_from_revision) FROM analytics.legacy_period_policy),0)
       OR NOT EXISTS(SELECT 1 FROM analytics.dataset_revision WHERE id=NEW.effective_from_revision AND cause='configuration') THEN
        RAISE EXCEPTION 'period policy requires a new unpublished configuration revision' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION analytics.guard_legacy_period_policy() OWNER TO migration_owner;

--
-- Name: legacy_csv_fact_digest(date, boolean); Type: FUNCTION; Schema: analytics; Owner: migration_owner
--

CREATE FUNCTION analytics.legacy_csv_fact_digest(p_month date, p_hot boolean DEFAULT false) RETURNS TABLE(row_count bigint, fact_digest text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'analytics', 'ingest'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE fact analytics.legacy_csv_snapshot_fact;chain bytea:=sha256(''::bytea);
BEGIN
    row_count:=0;
    FOR fact IN
        SELECT * FROM analytics.legacy_csv_snapshot_fact WHERE published_month=p_month AND NOT p_hot
        UNION ALL
        SELECT published_month,id,publication_id,observed_at,age_seconds,sampling_bucket,
            views_count,reactions_count,comments_count,shares_count,correction_sequence
        FROM ingest.publication_metric_snapshot WHERE published_month=p_month AND p_hot
        ORDER BY id
    LOOP
        chain:=sha256(chain||sha256(convert_to(to_jsonb(fact)::text,'UTF8')));row_count:=row_count+1;
    END LOOP;
    fact_digest:=encode(chain,'hex');RETURN NEXT;
END $$;


ALTER FUNCTION analytics.legacy_csv_fact_digest(p_month date, p_hot boolean) OWNER TO migration_owner;

