--
-- Name: rebuild_serving_projections(bigint); Type: FUNCTION; Schema: analytics; Owner: migration_owner
--

CREATE FUNCTION analytics.rebuild_serving_projections(p_dataset_revision_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'analytics'
    SET lock_timeout TO '10s'
    SET statement_timeout TO '2h'
    AS $$
DECLARE
    result jsonb;
BEGIN
    -- Publication history is part of the public revision boundary: detail and
    -- account reads must never expose an older history under a newer revision.
    -- Content and legacy CSV remain independently maintained compatibility data.
    result := analytics.rebuild_core_projections_v13(p_dataset_revision_id);
    RETURN result || jsonb_build_object(
        'official_account_ratings',
        analytics.refresh_official_account_ratings(p_dataset_revision_id),
        'publication_history_reactions',
        analytics.refresh_history_reaction_details(p_dataset_revision_id),
        'generation', 'serving'
    );
END
$$;


ALTER FUNCTION analytics.rebuild_serving_projections(p_dataset_revision_id bigint) OWNER TO migration_owner;

--
-- Name: FUNCTION rebuild_serving_projections(p_dataset_revision_id bigint); Type: COMMENT; Schema: analytics; Owner: migration_owner
--

COMMENT ON FUNCTION analytics.rebuild_serving_projections(p_dataset_revision_id bigint) IS 'Atomically publishes the seven API serving projections, including publication history, at a captured high-water mark without rebuilding content or legacy CSV exports.';


--
-- Name: refresh_history_reaction_details(bigint); Type: FUNCTION; Schema: analytics; Owner: migration_owner
--

CREATE FUNCTION analytics.refresh_history_reaction_details(p_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'analytics'
    AS $$
DECLARE written bigint;
BEGIN
    WITH history AS MATERIALIZED (
        SELECT item.*,
               lag(item.reaction_breakdown) OVER chronology AS prior_reactions,
               lag(item.reactions_count) OVER chronology AS prior_reactions_count
          FROM analytics.publication_history AS item
         WHERE dataset_revision_id = p_revision
        WINDOW chronology AS (
            PARTITION BY publication_id
            ORDER BY observed_at, published_month, snapshot_id
        )
    ), entries AS (
        SELECT history.*,
               coalesce(
                   analytics.ordered_history_reactions(
                       reaction_breakdown::text, false
                   ),
                   '[]'::jsonb
               ) AS current_entries,
               CASE
                 WHEN reactions_count IS NULL OR prior_reactions_count IS NULL
                   THEN NULL
                 ELSE (
                   SELECT coalesce(jsonb_agg(jsonb_build_object(
                       'reaction', key, 'count', difference
                   ) ORDER BY key COLLATE "C"), '[]'::jsonb)
                     FROM (
                       SELECT key,
                              coalesce((reaction_breakdown->>key)::bigint, 0)
                              - coalesce((prior_reactions->>key)::bigint, 0)
                              AS difference
                         FROM (
                           SELECT jsonb_object_keys(reaction_breakdown) AS key
                           UNION
                           SELECT jsonb_object_keys(prior_reactions) AS key
                         ) AS keys
                     ) AS deltas
                    WHERE difference <> 0
                 )
               END AS delta_entries
          FROM history
    )
    UPDATE analytics.publication_history AS target
       SET reaction_entries = entries.current_entries,
           delta_reaction_entries = entries.delta_entries,
           delta_reaction_breakdown = CASE
             WHEN entries.delta_entries IS NULL THEN NULL
             ELSE (
               SELECT coalesce(jsonb_object_agg(
                   value->>'reaction', value->'count'
               ), '{}'::jsonb)
                 FROM jsonb_array_elements(entries.delta_entries)
             )
           END,
           lineage = target.lineage || jsonb_build_object(
               'reactionDetailsSource', 'canonical'
           )
      FROM entries
     WHERE target.publication_id = entries.publication_id
       AND target.published_month = entries.published_month
       AND target.snapshot_id = entries.snapshot_id
       AND target.dataset_revision_id = p_revision;
    GET DIAGNOSTICS written = ROW_COUNT;
    RETURN written;
END
$$;


ALTER FUNCTION analytics.refresh_history_reaction_details(p_revision bigint) OWNER TO migration_owner;

--
-- Name: refresh_official_account_ratings(bigint); Type: FUNCTION; Schema: analytics; Owner: migration_owner
--

CREATE FUNCTION analytics.refresh_official_account_ratings(p_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'analytics', 'rating'
    AS $$
DECLARE written bigint;
BEGIN
    UPDATE analytics.legacy_overview_card
       SET rating_rank = NULL,
           rating_score = NULL,
           rating_period = NULL,
           rating_fetched_at = NULL
     WHERE platform = 'telegram'
       AND dataset_revision_id = p_revision;

    WITH latest AS (
        SELECT DISTINCT ON (observation.platform_account_id) observation.*
          FROM rating.official_account_rating_observation AS observation
          JOIN analytics.dataset_revision AS revision ON revision.id = p_revision
         WHERE observation.fetched_at <= revision.committed_at
         ORDER BY observation.platform_account_id,
                  observation.fetched_at DESC,
                  observation.id DESC
    )
    UPDATE analytics.legacy_overview_card AS card
       SET rating_rank = latest.rank,
           rating_score = latest.score,
           rating_period = latest.period,
           rating_fetched_at = latest.fetched_at
      FROM latest
     WHERE card.platform = 'telegram'
       AND card.entity_id = latest.platform_account_id
       AND card.dataset_revision_id = p_revision;
    GET DIAGNOSTICS written = ROW_COUNT;
    RETURN written;
END
$$;


ALTER FUNCTION analytics.refresh_official_account_ratings(p_revision bigint) OWNER TO migration_owner;

--
-- Name: refresh_publication_content(bigint); Type: FUNCTION; Schema: analytics; Owner: migration_owner
--

CREATE FUNCTION analytics.refresh_publication_content(p_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'analytics', 'ingest'
    AS $$
DECLARE rows_written bigint;
BEGIN
    INSERT INTO analytics.publication_content(
        publication_id, archived_text, dataset_revision_id
    )
    SELECT publication.id, NULL, p_revision
      FROM ingest.publication AS publication
      JOIN analytics.dataset_revision AS revision ON revision.id = p_revision
     WHERE publication.published_at <= revision.committed_at
    ON CONFLICT (publication_id) DO UPDATE
       SET dataset_revision_id = excluded.dataset_revision_id;
    GET DIAGNOSTICS rows_written = ROW_COUNT;
    INSERT INTO analytics.projection_state(
        projection_name, dataset_revision_id, status, refreshed_at, row_count
    ) VALUES (
        'publication_content', p_revision, 'ready',
        transaction_timestamp(), rows_written
    )
    ON CONFLICT(projection_name) DO UPDATE SET
        dataset_revision_id = excluded.dataset_revision_id,
        status = excluded.status,
        refreshed_at = excluded.refreshed_at,
        row_count = excluded.row_count,
        error_code = NULL;
    RETURN rows_written;
END
$$;


ALTER FUNCTION analytics.refresh_publication_content(p_revision bigint) OWNER TO migration_owner;

--
-- Name: require_completed_legacy_csv_restore(); Type: FUNCTION; Schema: analytics; Owner: migration_owner
--

CREATE FUNCTION analytics.require_completed_legacy_csv_restore() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'analytics'
    AS $$
BEGIN
    IF EXISTS(SELECT 1 FROM analytics.legacy_csv_restore_state WHERE manifest_id=NEW.manifest_id) THEN
        RAISE EXCEPTION 'incomplete archive restore cannot commit' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END $$;


ALTER FUNCTION analytics.require_completed_legacy_csv_restore() OWNER TO migration_owner;

--
-- Name: restore_legacy_csv_archive(uuid, text[], boolean); Type: FUNCTION; Schema: analytics; Owner: migration_owner
--

CREATE FUNCTION analytics.restore_legacy_csv_archive(p_manifest uuid, p_records text[], p_finish boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'analytics', 'ops_and_admin'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE state analytics.legacy_csv_restore_state;manifest ops_and_admin.archive_manifest;body text;data jsonb;
    fact analytics.legacy_csv_snapshot_fact;existing analytics.legacy_csv_snapshot_fact;actual record;
BEGIN
    SELECT * INTO STRICT manifest FROM ops_and_admin.archive_manifest WHERE id=p_manifest;
    IF manifest.dataset_type<>'publication_metric_snapshot' OR manifest.schema_version<>3 OR manifest.hot_dropped_at IS NULL
        OR manifest.canonical_sha256 IS NULL THEN RAISE EXCEPTION 'verified cold v3 manifest required'; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('observation-partition:'||manifest.partition_start::date::text,0));
    INSERT INTO analytics.legacy_csv_restore_state VALUES(p_manifest,pg_current_xact_id(),sha256(''::bytea),sha256(''::bytea),0,NULL)
        ON CONFLICT DO NOTHING;
    SELECT * INTO STRICT state FROM analytics.legacy_csv_restore_state WHERE manifest_id=p_manifest FOR UPDATE;
    IF state.transaction_id<>pg_current_xact_id() THEN RAISE EXCEPTION 'archive restore must use one transaction'; END IF;
    IF cardinality(p_records)>1000 THEN RAISE EXCEPTION 'archive restore batch exceeds 1000 rows'; END IF;
    FOREACH body IN ARRAY p_records LOOP
        data:=body::jsonb;
        fact:=ROW((data->>'published_month')::date,(data->>'id')::bigint,(data->>'publication_id')::uuid,
            (data->>'observed_at')::timestamptz,(data->>'age_seconds')::integer,(data->>'sampling_bucket')::bigint,
            (data->>'views_count')::bigint,(data->>'reactions_count')::bigint,(data->>'comments_count')::bigint,
            (data->>'shares_count')::bigint,(data->>'correction_sequence')::bigint);
        IF fact.published_month IS DISTINCT FROM manifest.partition_start::date
            OR (state.last_id IS NOT NULL AND fact.id<=state.last_id) THEN RAISE EXCEPTION 'archive month/order mismatch'; END IF;
        INSERT INTO analytics.legacy_csv_snapshot_fact SELECT fact.* ON CONFLICT DO NOTHING;
        SELECT * INTO STRICT existing FROM analytics.legacy_csv_snapshot_fact WHERE published_month=fact.published_month AND id=fact.id;
        IF existing IS DISTINCT FROM fact THEN RAISE EXCEPTION 'archive fact conflict' USING ERRCODE='23514'; END IF;
        state.chain:=sha256(state.chain||sha256(convert_to(body,'UTF8')));
        state.fact_chain:=sha256(state.fact_chain||sha256(convert_to(to_jsonb(fact)::text,'UTF8')));
        state.row_count:=state.row_count+1;state.last_id:=fact.id;
        IF state.row_count>manifest.row_count THEN RAISE EXCEPTION 'archive row limit exceeded'; END IF;
    END LOOP;
    UPDATE analytics.legacy_csv_restore_state SET chain=state.chain,fact_chain=state.fact_chain,row_count=state.row_count,last_id=state.last_id
        WHERE manifest_id=p_manifest;
    IF p_finish THEN
        SELECT * INTO actual FROM analytics.legacy_csv_fact_digest(manifest.partition_start::date,false);
        IF state.row_count<>manifest.row_count OR encode(state.chain,'hex')<>manifest.canonical_sha256
            OR actual.row_count<>state.row_count OR actual.fact_digest<>encode(state.fact_chain,'hex') THEN
            RAISE EXCEPTION 'archive canonical/CSV coverage mismatch' USING ERRCODE='23514';
        END IF;
        INSERT INTO analytics.legacy_csv_archive_coverage(manifest_id,published_month,row_count,fact_digest,canonical_sha256)
            VALUES(p_manifest,manifest.partition_start::date,actual.row_count,actual.fact_digest,manifest.canonical_sha256) ON CONFLICT DO NOTHING;
        IF NOT EXISTS(SELECT 1 FROM analytics.legacy_csv_archive_coverage WHERE manifest_id=p_manifest
            AND row_count=actual.row_count AND fact_digest=actual.fact_digest AND canonical_sha256=manifest.canonical_sha256) THEN
            RAISE EXCEPTION 'existing archive coverage conflict' USING ERRCODE='23514';
        END IF;
        DELETE FROM analytics.legacy_csv_restore_state WHERE manifest_id=p_manifest;
    END IF;
    RETURN state.row_count;
END $$;


ALTER FUNCTION analytics.restore_legacy_csv_archive(p_manifest uuid, p_records text[], p_finish boolean) OWNER TO migration_owner;

--
-- Name: guard_account_identity_history(); Type: FUNCTION; Schema: catalog; Owner: migration_owner
--

CREATE FUNCTION catalog.guard_account_identity_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'account identity history is append-only' USING ERRCODE='55000';
    END IF;
    IF OLD.valid_to IS NOT NULL OR NEW.valid_to IS NULL
       OR NEW.valid_to <= OLD.valid_from
       OR (to_jsonb(NEW)-'valid_to') IS DISTINCT FROM (to_jsonb(OLD)-'valid_to') THEN
        RAISE EXCEPTION 'only closing the current account identity version is allowed' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION catalog.guard_account_identity_history() OWNER TO migration_owner;

--
-- Name: guard_canonical_account_identity(); Type: FUNCTION; Schema: catalog; Owner: migration_owner
--

CREATE FUNCTION catalog.guard_canonical_account_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.platform IS DISTINCT FROM OLD.platform
       OR NEW.canonical_external_id IS DISTINCT FROM OLD.canonical_external_id THEN
        RAISE EXCEPTION 'canonical account identity is immutable' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION catalog.guard_canonical_account_identity() OWNER TO migration_owner;

--
-- Name: assert_publication_snapshot_month(); Type: FUNCTION; Schema: ingest; Owner: migration_owner
--

CREATE FUNCTION ingest.assert_publication_snapshot_month() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ingest'
    AS $$
DECLARE
    expected_month date;
BEGIN
    SELECT date_trunc('month', published_at AT TIME ZONE 'UTC')::date
      INTO expected_month
      FROM ingest.publication
     WHERE id = NEW.publication_id;
    IF expected_month IS NULL OR expected_month <> NEW.published_month THEN
        RAISE EXCEPTION 'published_month % does not match publication % month %',
            NEW.published_month, NEW.publication_id, expected_month;
    END IF;
    RETURN NEW;
END
$$;


ALTER FUNCTION ingest.assert_publication_snapshot_month() OWNER TO migration_owner;

--
-- Name: fence_reaction_insert(); Type: FUNCTION; Schema: ingest; Owner: migration_owner
--

CREATE FUNCTION ingest.fence_reaction_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ingest', 'ops_and_admin'
    AS $$
DECLARE snapshot_xid xid8; previous_count bigint;
BEGIN
 PERFORM ops_and_admin.assert_publication_partition_writable(NEW.snapshot_published_month);
 SELECT reaction_count INTO previous_count FROM ingest.reaction_breakdown
 WHERE snapshot_published_month=NEW.snapshot_published_month AND snapshot_id=NEW.snapshot_id AND reaction_key=NEW.reaction_key;
 IF FOUND THEN
   IF previous_count=NEW.reaction_count THEN RETURN NULL; END IF;
   RAISE EXCEPTION 'reaction replay differs from immutable observation' USING ERRCODE='55000';
 END IF;
 SELECT ingested_xid INTO snapshot_xid FROM ingest.publication_metric_snapshot
 WHERE published_month=NEW.snapshot_published_month AND id=NEW.snapshot_id;
 -- Breakdown must be committed with its parent. Later additions change the
 -- event fingerprint and therefore must belong to a new correction snapshot.
 IF snapshot_xid IS DISTINCT FROM pg_current_xact_id() THEN
   RAISE EXCEPTION 'reaction breakdown must be inserted with its observation' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION ingest.fence_reaction_insert() OWNER TO migration_owner;

--
-- Name: prepare_immutable_account_snapshot(); Type: FUNCTION; Schema: ingest; Owner: migration_owner
--

CREATE FUNCTION ingest.prepare_immutable_account_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ingest'
    AS $$
DECLARE previous ingest.account_metric_snapshot%ROWTYPE;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('account-observation:'||NEW.platform_account_id::text||':'||NEW.observed_at::text,0));
 NEW.subscriber_quality:=coalesce(NEW.subscriber_quality,NEW.quality);
 SELECT * INTO previous FROM ingest.account_metric_snapshot
  WHERE platform_account_id=NEW.platform_account_id AND observed_at=NEW.observed_at AND source_fingerprint=NEW.source_fingerprint;
 IF FOUND THEN
   IF (to_jsonb(previous)-ARRAY['id','created_at','collection_run_id','correction_sequence','supersedes_snapshot_id','correction_reason','ingested_xid'])
    IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['id','created_at','collection_run_id','correction_sequence','supersedes_snapshot_id','correction_reason','ingested_xid']) THEN
     RAISE EXCEPTION 'fingerprint reused for different observation' USING ERRCODE='23505';
   END IF;
   RETURN NULL;
 END IF;
 SELECT * INTO previous FROM ingest.account_metric_snapshot
  WHERE platform_account_id=NEW.platform_account_id AND observed_at=NEW.observed_at ORDER BY correction_sequence DESC LIMIT 1;
 NEW.correction_sequence:=CASE WHEN FOUND THEN previous.correction_sequence+1 ELSE 0 END;
 NEW.supersedes_snapshot_id:=previous.id;
 NEW.correction_reason:=CASE WHEN previous.id IS NOT NULL THEN coalesce(nullif(btrim(NEW.correction_reason),''),'provider_payload_changed') END;
 RETURN NEW;
END $$;


ALTER FUNCTION ingest.prepare_immutable_account_snapshot() OWNER TO migration_owner;

--
-- Name: prepare_immutable_publication_snapshot(); Type: FUNCTION; Schema: ingest; Owner: migration_owner
--

CREATE FUNCTION ingest.prepare_immutable_publication_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ingest', 'ops_and_admin'
    AS $$
DECLARE previous ingest.publication_metric_snapshot%ROWTYPE;
BEGIN
 NEW.ingested_xid:=pg_current_xact_id();
 PERFORM ops_and_admin.assert_publication_partition_writable(NEW.published_month);
 PERFORM pg_advisory_xact_lock(hashtextextended('observation:'||NEW.published_month::text||':'||NEW.publication_id::text||':'||NEW.sampling_bucket::text,0));
 NEW.views_quality:=coalesce(NEW.views_quality,NEW.quality);
 NEW.reactions_quality:=coalesce(NEW.reactions_quality,NEW.quality);
 NEW.comments_quality:=coalesce(NEW.comments_quality,NEW.quality);
 NEW.shares_quality:=coalesce(NEW.shares_quality,NEW.quality);
 SELECT * INTO previous FROM ingest.publication_metric_snapshot
  WHERE published_month=NEW.published_month AND publication_id=NEW.publication_id
   AND sampling_bucket=NEW.sampling_bucket AND source_fingerprint=NEW.source_fingerprint;
 IF FOUND THEN
   IF (to_jsonb(previous)-ARRAY['id','created_at','collection_run_id','correction_sequence','supersedes_snapshot_id','correction_reason','ingested_xid'])
    IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['id','created_at','collection_run_id','correction_sequence','supersedes_snapshot_id','correction_reason','ingested_xid']) THEN
     RAISE EXCEPTION 'fingerprint reused for different observation' USING ERRCODE='23505';
   END IF;
   RETURN NULL;
 END IF;
 SELECT * INTO previous FROM ingest.publication_metric_snapshot
  WHERE published_month=NEW.published_month AND publication_id=NEW.publication_id
   AND sampling_bucket=NEW.sampling_bucket ORDER BY correction_sequence DESC LIMIT 1;
 NEW.correction_sequence:=CASE WHEN FOUND THEN previous.correction_sequence+1 ELSE 0 END;
 NEW.supersedes_snapshot_id:=previous.id;
 NEW.correction_reason:=CASE WHEN previous.id IS NOT NULL THEN coalesce(nullif(btrim(NEW.correction_reason),''),'provider_payload_changed') END;
 RETURN NEW;
END $$;


ALTER FUNCTION ingest.prepare_immutable_publication_snapshot() OWNER TO migration_owner;

--
-- Name: reject_new_unavailable_evidence(); Type: FUNCTION; Schema: ingest; Owner: migration_owner
--

CREATE FUNCTION ingest.reject_new_unavailable_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.legacy_evidence_unavailable THEN RAISE EXCEPTION 'new evidence must be retrievable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION ingest.reject_new_unavailable_evidence() OWNER TO migration_owner;

