--

COMMENT ON COLUMN ingest.account_metric_snapshot.collected_at IS 'UTC instant when the target collector received the observation.';


--
-- Name: COLUMN account_metric_snapshot.semantic_fingerprint; Type: COMMENT; Schema: ingest; Owner: migration_owner
--

COMMENT ON COLUMN ingest.account_metric_snapshot.semantic_fingerprint IS 'SHA-256 of versioned subscriber value/display/quality semantics, excluding poll, run, collector version and transport timestamps. NULL only for rows preceding the consolidated V31 transition.';


--
-- Name: account_metric_snapshot_active; Type: VIEW; Schema: ingest; Owner: migration_owner
--

CREATE VIEW ingest.account_metric_snapshot_active AS
 SELECT id,
    platform_account_id,
    collection_run_id,
    observed_at,
    subscriber_count,
    subscriber_display,
    quality,
    source_fingerprint,
    created_at,
    collected_at,
    correction_sequence,
    supersedes_snapshot_id,
    correction_reason,
    subscriber_quality,
    subscriber_source_field,
    subscriber_semantic_flags,
    semantic_fingerprint
   FROM ingest.account_metric_snapshot snapshot
  WHERE (NOT (EXISTS ( SELECT 1
           FROM ingest.account_metric_snapshot successor
          WHERE ((successor.platform_account_id = snapshot.platform_account_id) AND (successor.observed_at = snapshot.observed_at) AND (successor.correction_sequence > snapshot.correction_sequence)))));


