);


ALTER TABLE ops_and_admin.retention_policy OWNER TO migration_owner;

-- A clean final-schema install must be publishable without an undocumented
-- manual seed.  Ninety days preserves the 70-day comparison/history floor and
-- remains a policy row that operators may raise explicitly after rehearsal.
INSERT INTO ops_and_admin.retention_policy (
    data_class, hot_days, retention_months, archive_required, notes
) VALUES (
    'publication_metric_snapshot', 90, NULL, true,
    'Default final-schema hot window; do not reduce below 70 days during parity.'
);

